H.background();
const v = H.plot2d({ xMin: 0, xMax: 20, yMin: -3, yMax: 7 });
v.grid(); v.axes();
const F = P.F, m = Math.max(0.1, P.m);
const a = F / m;                       // Newton's 2nd law: a = F/m
// Cart starts at rest, accelerates under F, resets when it reaches the wall.
const track = 18;
const period = a > 1e-6 ? Math.sqrt(2 * track / a) + 1.2 : 6;
const tc = t % period;
let x, vel;
if (a > 1e-6) {
  const tReach = Math.sqrt(2 * track / a);
  if (tc < tReach) { x = 0.5 * a * tc * tc; vel = a * tc; }
  else { x = track; vel = a * tReach; }
} else { x = 0; vel = 0; }
x = Math.min(x, track);
const yTrack = 0;
v.line(0, yTrack, 20, yTrack, { color: H.colors.axis, width: 2 });
// cart body
v.rect(x - 0.6, yTrack, 1.2, 0.9, { fill: H.colors.accent, stroke: H.colors.bg, width: 2 });
// applied force arrow (constant, points in motion direction)
const fLen = Math.min(6, Math.abs(F) * 0.5);
v.arrow(x, yTrack + 0.45, x + (F >= 0 ? fLen : -fLen), yTrack + 0.45, { color: H.colors.warn, width: 4 });
// velocity arrow
if (vel > 0.01) v.arrow(x, yTrack + 1.8, x + Math.min(6, vel * 0.5), yTrack + 1.8, { color: H.colors.good, width: 3 });
H.text("Newton's 2nd law:  F = m·a", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("a = F / m = " + F.toFixed(1) + " / " + m.toFixed(1) + " = " + a.toFixed(2) + " m/s²", 24, 52, { color: H.colors.sub, size: 13 });
H.text("v = " + vel.toFixed(2) + " m/s    x = " + x.toFixed(2) + " m", 24, 74, { color: H.colors.sub, size: 13 });
H.legend([{ label: "force F (N)", color: H.colors.warn }, { label: "velocity v", color: H.colors.good }], H.W - 170, 28);
